"""Audio device discovery and selection."""

from __future__ import annotations

import sounddevice as sd


def list_input_devices() -> list[dict]:
    """List all available audio input devices."""
    devices = sd.query_devices()
    result = []
    for i, dev in enumerate(devices):
        if dev["max_input_channels"] > 0:
            result.append(
                {
                    "index": i,
                    "name": dev["name"],
                    "max_input_channels": dev["max_input_channels"],
                    "default_samplerate": dev["default_samplerate"],
                }
            )
    return result


def find_blackhole_device() -> dict | None:
    """Find the BlackHole virtual audio device (system audio capture)."""
    for dev in list_input_devices():
        if "blackhole" in dev["name"].lower():
            return dev
    return None


def find_default_mic() -> dict | None:
    """Find the default microphone input device."""
    try:
        default_idx = sd.default.device[0]  # default input device index
        if default_idx is not None and default_idx >= 0:
            dev = sd.query_devices(default_idx)
            if dev["max_input_channels"] > 0:
                return {
                    "index": default_idx,
                    "name": dev["name"],
                    "max_input_channels": dev["max_input_channels"],
                    "default_samplerate": dev["default_samplerate"],
                }
    except Exception:
        pass

    # Fallback: find any built-in mic
    for dev in list_input_devices():
        name = dev["name"].lower()
        if "macbook" in name or "built-in" in name:
            return dev

    # Last resort: first available input
    inputs = list_input_devices()
    if inputs:
        return inputs[0]
    return None


def resolve_devices(
    mic_device_index: int | None = None,
    system_device_index: int | None = None,
) -> tuple[dict | None, dict | None]:
    """Resolve mic and system audio devices.

    Returns (mic_device, system_device) dicts. Either can be None if unavailable.
    """
    mic = None
    system = None

    if mic_device_index is not None:
        dev = sd.query_devices(mic_device_index)
        mic = {
            "index": mic_device_index,
            "name": dev["name"],
            "max_input_channels": dev["max_input_channels"],
            "default_samplerate": dev["default_samplerate"],
        }
    else:
        mic = find_default_mic()

    if system_device_index is not None:
        dev = sd.query_devices(system_device_index)
        system = {
            "index": system_device_index,
            "name": dev["name"],
            "max_input_channels": dev["max_input_channels"],
            "default_samplerate": dev["default_samplerate"],
        }
    else:
        system = find_blackhole_device()

    # Don't use the same device for both
    if mic and system and mic["index"] == system["index"]:
        system = None

    return mic, system

