"""Data models for sessions and transcript entries."""

from __future__ import annotations

import json
import time
import uuid
from dataclasses import dataclass, field


@dataclass
class TranscriptEntry:
    """A single transcript segment."""

    timestamp: float  # wall-clock time (epoch seconds)
    end_timestamp: float
    speaker: str  # "mic", "system", or a mapped name
    text: str

    def to_dict(self) -> dict:
        return {
            "timestamp": self.timestamp,
            "end_timestamp": self.end_timestamp,
            "speaker": self.speaker,
            "text": self.text,
        }

    @classmethod
    def from_dict(cls, d: dict) -> TranscriptEntry:
        return cls(
            timestamp=d["timestamp"],
            end_timestamp=d["end_timestamp"],
            speaker=d["speaker"],
            text=d["text"],
        )

    def format_text(self, session_start: float) -> str:
        """Format as readable text with relative timestamp."""
        relative = self.timestamp - session_start
        minutes = int(relative // 60)
        seconds = int(relative % 60)
        return f"[{minutes:02d}:{seconds:02d}] {self.speaker}: {self.text}"


@dataclass
class SessionMeta:
    """Metadata for a recording session."""

    session_id: str
    start_time: float
    end_time: float | None = None
    context: str = ""
    mic_device_name: str | None = None
    system_device_name: str | None = None
    speaker_names: dict[str, str] = field(default_factory=dict)

    @property
    def is_active(self) -> bool:
        return self.end_time is None

    @property
    def duration_seconds(self) -> float:
        end = self.end_time or time.time()
        return end - self.start_time

    def to_dict(self) -> dict:
        return {
            "session_id": self.session_id,
            "start_time": self.start_time,
            "end_time": self.end_time,
            "context": self.context,
            "mic_device_name": self.mic_device_name,
            "system_device_name": self.system_device_name,
            "speaker_names": self.speaker_names,
        }

    @classmethod
    def from_dict(cls, d: dict) -> SessionMeta:
        return cls(
            session_id=d["session_id"],
            start_time=d["start_time"],
            end_time=d.get("end_time"),
            context=d.get("context", ""),
            mic_device_name=d.get("mic_device_name"),
            system_device_name=d.get("system_device_name"),
            speaker_names=d.get("speaker_names", {}),
        )

    @classmethod
    def create(
        cls,
        context: str = "",
        mic_device_name: str | None = None,
        system_device_name: str | None = None,
    ) -> SessionMeta:
        return cls(
            session_id=uuid.uuid4().hex[:12],
            start_time=time.time(),
            context=context,
            mic_device_name=mic_device_name,
            system_device_name=system_device_name,
        )

