"""JSONL-based transcript storage and session index."""

from __future__ import annotations

import json
import logging
import threading
from pathlib import Path

from meeting_copilot.session.models import SessionMeta, TranscriptEntry

logger = logging.getLogger(__name__)


class SessionStorage:
    """Manages session data on disk.

    Layout:
        data_dir/
            sessions.json          # Index of all sessions
            sessions/
                {session_id}/
                    meta.json      # Session metadata
                    transcript.jsonl  # One JSON object per line
                    recording.wav  # Optional audio recording
    """

    def __init__(self, data_dir: Path):
        self.data_dir = data_dir
        self._lock = threading.Lock()
        self.data_dir.mkdir(parents=True, exist_ok=True)

    def _session_dir(self, session_id: str) -> Path:
        d = self.data_dir / "sessions" / session_id
        d.mkdir(parents=True, exist_ok=True)
        return d

    def _transcript_path(self, session_id: str) -> Path:
        return self._session_dir(session_id) / "transcript.jsonl"

    def _meta_path(self, session_id: str) -> Path:
        return self._session_dir(session_id) / "meta.json"

    def recording_path(self, session_id: str) -> Path:
        return self._session_dir(session_id) / "recording.wav"

    # --- Session metadata ---

    def save_meta(self, meta: SessionMeta) -> None:
        path = self._meta_path(meta.session_id)
        with self._lock:
            path.write_text(json.dumps(meta.to_dict(), indent=2))

    def load_meta(self, session_id: str) -> SessionMeta | None:
        path = self._meta_path(session_id)
        if not path.exists():
            return None
        return SessionMeta.from_dict(json.loads(path.read_text()))

    def list_sessions(self) -> list[SessionMeta]:
        sessions_dir = self.data_dir / "sessions"
        if not sessions_dir.exists():
            return []

        metas = []
        for d in sorted(sessions_dir.iterdir()):
            meta_path = d / "meta.json"
            if meta_path.exists():
                try:
                    metas.append(SessionMeta.from_dict(json.loads(meta_path.read_text())))
                except (json.JSONDecodeError, KeyError):
                    logger.warning("Corrupt session metadata: %s", meta_path)
        return metas

    # --- Transcript entries ---

    def append_entry(self, session_id: str, entry: TranscriptEntry) -> None:
        """Append a transcript entry. Thread-safe."""
        path = self._transcript_path(session_id)
        line = json.dumps(entry.to_dict()) + "\n"
        with self._lock:
            with open(path, "a") as f:
                f.write(line)

    def read_entries(self, session_id: str) -> list[TranscriptEntry]:
        """Read all transcript entries for a session."""
        path = self._transcript_path(session_id)
        if not path.exists():
            return []

        entries = []
        for line in path.read_text().strip().splitlines():
            if line:
                try:
                    entries.append(TranscriptEntry.from_dict(json.loads(line)))
                except (json.JSONDecodeError, KeyError):
                    continue
        return entries

    def entry_count(self, session_id: str) -> int:
        path = self._transcript_path(session_id)
        if not path.exists():
            return 0
        return sum(1 for line in path.read_text().strip().splitlines() if line)

    # --- Deletion ---

    def delete_session(self, session_id: str) -> bool:
        session_dir = self.data_dir / "sessions" / session_id
        if not session_dir.exists():
            return False

        import shutil

        shutil.rmtree(session_dir)
        return True

